msgs = [base64.b64decode(l.strip()) for l in b64_lines if l.strip()]
print("count:", len(msgs), "lengths:", set(len(m) for m in msgs))

L = max(len(m) for m in msgs)

# majority-vote keystream assuming most bytes at each position are space padding
keystream = bytearray(L)
for i in range(L):
    counts = Counter(m[i] for m in msgs if i < len(m))
    common_byte, freq = counts.most_common(1)[0]
    keystream[i] = common_byte ^ 0x20  # assume space

decoded = []
for idx, m in enumerate(msgs):
    pt = bytes(c ^ keystream[i] for i, c in enumerate(m))
    decoded.append(pt)
    print(idx, pt)
